const b = $input.first().json.body || $input.first().json || {};
const event = String(b.event || 'discord_funnel_sync');
const email = String(b.email || '').toLowerCase();
const uid = String(b.discord_user_id || '');
const tier = String(b.tier || b.status || 'prospect');
if ($env.MONGODB_URI && (email || uid)) {
  try {
    const { MongoClient } = require('mongodb');
    const c = new MongoClient($env.MONGODB_URI);
    await c.connect();
    const db = c.db($env.MONGODB_DB || 'tradesejon_prod');
    await db.collection('leads').updateOne(
      email ? { email } : { discord_user_id: uid },
      { $set: { discord_user_id: uid, tier, last_event: event, updatedAt: new Date() }, $setOnInsert: { createdAt: new Date() } },
      { upsert: true }
    );
    await c.close();
  } catch (e) {}
}
return [{ json: { ok: true, synced: true, event, discord_user_id: uid, tier, timestamp: new Date().toISOString() } }];
